css:
.btn-wrapper {
  --width: 140px;
  --height: 60px;
  --padding: 6px;
  --border-radius: 30px;
  --dot-size: 12px;
  --btn-color: #202020;
  --hue: 355deg;
  --animation-duration: 1.2s;

  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--width);
  height: var(--height);
  border-radius: var(--border-radius);
  border: none;

  background-color: #00000008;

  box-shadow:
    1px 1px 2px 0 #fffd,
    2px 2px 2px #0001 inset,
    2px 2px 4px #0001 inset,
    2px 2px 8px #0001 inset;

  transition: box-shadow 50ms linear;

  perspective: 150px;
  perspective-origin: center;

  user-select: none;
  z-index: 1;
}

.btn {
  display: flex;
  align-items: center;
  justify-content: start;
  gap: 0.25em;
  text-align: left;
  padding: 0 var(--height) 0 calc(var(--padding) * 4);

  width: calc(100% - 2 * var(--padding));
  height: calc(100% - 2 * var(--padding));
  border-radius: calc(var(--border-radius) - var(--padding));
  border: none;
  cursor: pointer;

  background: linear-gradient(#fff2, #0001), var(--btn-color);

  box-shadow:
    1px 1px 2px -1px #fff inset,
    0 2px 1px #00000010,
    0 4px 2px #00000010,
    0 8px 4px #00000010,
    0 16px 8px #00000010,
    0 32px 16px #00000010;

  transition:
    transform 0.25s cubic-bezier(0.25, 1.5, 0.5, 2.2),
    box-shadow 0.25s cubic-bezier(0.25, 1.5, 0.5, 1),
    filter 0.3s cubic-bezier(0.25, 1.5, 0.5, 1);
  will-change: transform, filter;

  z-index: 2;
}

.btn-txt {
  display: inline-block;

  font-size: 16px;
  font-weight: 600;
  font-family: "Montserrat", "Manrope", sans-serif;
  letter-spacing: 1px;

  color: #fff9;
  background-image: linear-gradient(#fffc, #000a);
  background-clip: text;
  filter: drop-shadow(0 1px 0px #fff8) drop-shadow(0 -1px 0px #0006);
}

.disclaimer-txt {
  position: absolute;
  left: var(--border-radius);
  bottom: -24px;
  font-family: "Montserrat", "Manrope", sans-serif;
  font-size: 12px;
  color: #0009;
}

.dot {
  position: absolute;
  top: calc(50% - var(--dot-size) / 2);
  right: calc(var(--height) / 2 - var(--padding) / 2);
  width: var(--dot-size);
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background-color: hsla(var(--hue), 0%, 50%, 0.1);

  border: 1px solid hsla(var(--hue), 0%, 60%, 0.6);
  box-sizing: border-box;

  box-shadow:
    1px 1px 2px -1px #fffe inset,
    0 2px 1px #00000010,
    0 4px 2px #00000010,
    0 8px 4px #00000010;

  pointer-events: none;
  z-index: 3;
}

.dot::before {
  content: "";
  position: absolute;
  top: calc(var(--padding) / -2);
  left: calc(var(--padding) / -2);
  width: calc(100% + var(--padding));
  height: calc(100% + var(--padding));
  border-radius: inherit;
  background-color: #0006;
  mask-image: radial-gradient(circle at 50% 60%, transparent 50%, black);
}

.dot::after {
  content: "";
  position: absolute;
  top: calc(var(--padding) / -2);
  left: calc(var(--padding) / -2);
  width: calc(100% + var(--padding));
  height: calc(100% + var(--padding));
  border-radius: inherit;
  background-color: #0000;

  box-shadow:
    0 0 10px 2px hsla(var(--hue), 80%, 50%, 0.3),
    0 0 20px 10px hsla(var(--hue), 80%, 50%, 0.5),
    0 0 50px 20px hsla(var(--hue), 80%, 50%, 0.5),
    0 0 16px 1px hsla(var(--hue), 100%, 60%, 0.9) inset;

  opacity: 0;
}

@keyframes bg-anim {
  0%,
  100% {
    background-color: hsla(var(--hue), 50%, 50%, 0);
  }
  50% {
    background-color: hsla(var(--hue), 100%, 50%, 1);
  }
}

@keyframes opacity-anim {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

.btn:hover,
.btn:focus-visible {
  filter: drop-shadow(
    var(--padding) 0 var(--padding) hsla(var(--hue), 70%, 60%, 0.6)
  );
  transform: translate3d(0, 0px, 3px);

  .btn-txt {
    background-color: hsla(var(--hue), 50%, 50%, 1);
    background-image: none;
  }

  .pulse {
    &.dot {
      animation: none;
      background-color: hsla(var(--hue), 100%, 50%, 1);
    }
    &::after {
      animation: none;
      opacity: 1;
    }
  }
}

.btn:focus-visible {
  outline: 2px dashed hsla(var(--hue), 70%, 40%, 1);
  outline-offset: var(--padding);
}

.btn:focus {
  .pulse {
    transition: transform 200ms ease-in;

    &.dot {
      animation: bg-anim var(--animation-duration) ease-in-out infinite;
    }

    &::after {
      animation: opacity-anim var(--animation-duration) ease-in-out infinite;
    }
  }
}

.btn:active {
  filter: drop-shadow(
    var(--padding) 0 var(--padding) hsla(var(--hue), 100%, 50%, 1)
  );
  transform: translate3d(0, 0, -4px);

  .btn-txt {
    background-color: hsla(var(--hue), 50%, 50%, 1);
  }

  ~ .dot {
    animation-play-state: paused;
    background-color: hsla(var(--hue), 100%, 50%, 1);
  }
}

.btn-wrapper:has(.btn:active) {
  box-shadow:
    1px 1px 2px 0 #fff,
    2px 2px 2px #0001 inset,
    2px 2px 4px #0001 inset,
    2px 2px 8px #0001 inset,
    0 0 32px 2px hsla(var(--hue), 50%, 50%, 0.5) inset;
}
